package com.nopilot.aiservice.util;  import java.util.Locale; import java.util.Map; import java.util.Set;  /**  * Maps a file path to a language label, or null when the file type is not worth indexing.  * Labels match those produced by repository-service (JAVA, PYTHON, JAVASCRIPT, TYPESCRIPT,  * DOCUMENTATION, CONFIG).  */ public final class LanguageDetector {      public static final String JAVA = "JAVA";     public static final String PYTHON = "PYTHON";     public static final String JAVASCRIPT = "JAVASCRIPT";     public static final String TYPESCRIPT = "TYPESCRIPT";     public static final String DOCUMENTATION = "DOCUMENTATION";     public static final String CONFIG = "CONFIG";      private static final Map<String, String> BY_EXTENSION = Map.of(             "java", JAVA,             "py", PYTHON,             "js", JAVASCRIPT,             "jsx", JAVASCRIPT,             "mjs", JAVASCRIPT,             "ts", TYPESCRIPT,             "tsx", TYPESCRIPT     );      private static final Set<String> DOC_EXTENSIONS = Set.of("md", "markdown", "rst", "adoc", "txt");      private static final Set<String> CONFIG_NAMES = Set.of(             "pom.xml", "build.gradle", "build.gradle.kts", "settings.gradle", "settings.gradle.kts",             "package.json", "tsconfig.json", "pyproject.toml", "setup.cfg", "pipfile",             "dockerfile", "docker-compose.yml", "docker-compose.yaml", "makefile", ".env.example"     );      private LanguageDetector() {     }      /** @return the language label, or null if the file should not be indexed. */     public static String detect(String path) {          if (path == null || path.isBlank()) {             return null;         }          String name = fileName(path).toLowerCase(Locale.ROOT);         String extension = extension(name);          String language = BY_EXTENSION.get(extension);         if (language != null) {             return language;         }          if (name.startsWith("readme") || DOC_EXTENSIONS.contains(extension)) {             return DOCUMENTATION;         }          if (CONFIG_NAMES.contains(name)                 || (name.startsWith("application") && isYamlOrProperties(extension))                 || (name.startsWith("requirements") && extension.equals("txt"))) {             return CONFIG;         }          return null;     }      public static String fileName(String path) {         return path.substring(path.lastIndexOf('/') + 1);     }      private static String extension(String name) {         int dot = name.lastIndexOf('.');         return dot < 0 ? "" : name.substring(dot + 1);     }      private static boolean isYamlOrProperties(String extension) {         return extension.equals("yml") || extension.equals("yaml") || extension.equals("properties");     } }
